#pragma once
// include/core/build_info.hpp
// How this executable was built, for the F06 run header. The values are
// generated by Meson (src/core/build_info.cpp.in).

#include <string_view>

namespace vibestran {

struct BuildInfo {
  std::string_view version;    ///< project version from meson.build
  std::string_view revision;   ///< `git describe --always --dirty`, or "unknown"
  std::string_view build_type; ///< Meson buildtype, e.g. "release"
  std::string_view compiler;   ///< C++ compiler id and version
  std::string_view platform;   ///< host system and CPU family
  std::string_view components; ///< optional libraries and backends compiled in
};

[[nodiscard]] const BuildInfo &build_info() noexcept;

} // namespace vibestran
